INSERT INTO memories (id,payload,published) VALUES ('shinobu-aberration-killer','{"id": "shinobu-aberration-killer", "character_ko": "오시노 시노부", "character_ja": "忍野忍", "name_ko": "괴이 살해", "name_ja": "怪異殺し", "rarity": 5, "role": "어태커", "element": "불속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9145, "공격력": 3948, "방어력": 2940, "스피드": 100}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/shinobu-aberration-killer-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HE9kZw-aoAAo_LS.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "怪異殺し", "name_ko": "괴이 살해", "ja": "敵単体に500%の火属性ダメージを与える。\n自身の【追撃】で与えるダメージ+60%(2ターン)、チャージ+30%", "ko": "적 하나에게 500%의 불속성 피해를 준다.\n자신의 【추격】으로 주는 피해 +60%(2턴), 차지 +30%.", "cost": "MP 100", "break": 35}, {"kind": "전투 스킬", "name_ja": "潜影", "name_ko": "잠영", "ja": "敵単体に270%の火属性ダメージを与える。\n自身に攻撃力+25%(2ターン)、不死の魔法少女(2ターン)を付与し、チャージ+20%。", "ko": "적 하나에게 270%의 불속성 피해를 준다.\n자신에게 공격력 +25%(2턴), 불사의 마법소녀(2턴)를 부여하고, 차지 +20%.", "cost": null, "break": 20}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "不死の魔法少女", "name_ko": "불사의 마법소녀", "ja": "弱点属性に対して与えるダメージ+20%。\n敵にダメージを与えたときスピード+5%(累積4回)。\n自身以外の味方がダメージを与えたとき自身のチャージ+5%", "ko": "약점 속성에 대해 주는 피해 +20%.\n적에게 피해를 주면 스피드 +5%(4회 중첩).\n자신 이외의 아군이 피해를 주면 자신의 차지 +5%.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の火属性ダメージを与える。\n自身のチャージ+5%", "ko": "적 하나에게 100%의 불속성 피해를 준다.\n자신의 차지 +5%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ヒールチェイス", "name_ko": "힐 체이스", "ja": "バトル開始時にチャージ0%(最大100%)。\n自身が敵を攻撃したとき自身のHPを発動者のHP3%回復する。\n敵がブレイクしたとき、または自身のチャージが100%のとき【追撃】を発動する。\n※それぞれの条件ごとに【追撃】が発動。", "ko": "전투 시작 시 차지 0%(최대 100%).\n자신이 적을 공격하면 자신의 HP를 발동자 HP의 3%만큼 회복한다.\n적이 브레이크되었을 때 또는 자신의 차지가 100%일 때 【추격】을 발동한다.\n※ 각 조건마다 【추격】이 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 추격", "name_ja": "追撃", "name_ko": "추격", "ja": "敵単体に135%の火属性ダメージを与え、自身のMP+10。\n自身のチャージが100%のときチャージ-100%", "ko": "적 하나에게 135%의 불속성 피해를 주고, 자신의 MP +10.\n자신의 차지가 100%이면 차지 -100%.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "アサルトヒール", "name_ko": "어설트 힐", "ja": "【アタッカーに装備時】\n攻撃力+15%、スピード+10%。\n自身が敵を攻撃したとき自身のHPを発動者のHP2%回復する", "ko": "【어태커에게 장착 시】\n공격력 +15%, 스피드 +10%.\n자신이 적을 공격하면 자신의 HP를 발동자 HP의 2%만큼 회복한다.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "すべて二刀のもとに伏してやろう", "name_ko": "모두 두 자루의 칼 아래 굴복시켜 주마", "ja": "与えるダメージ+20%。\nHP回復量+10%", "ko": "주는 피해 +20%.\nHP 회복량 +10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときMP+10%、攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 MP +10%, 공격력 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n【追撃】の与えるダメージ+20%。\n自身が【追撃】を発動したとき与えるダメージ+5%(累積4回)", "ko": "HP·공격력·방어력 +2%.\n【추격】이 주는 피해 +20%.\n자신이 【추격】을 발동하면 주는 피해 +5%(4회 중첩)."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵のブレイクボーナスが最大になったとき追加ターンを獲得する", "ko": "HP·공격력·방어력 +2%.\n적의 브레이크 보너스가 최대가 되면 추가 턴을 얻는다."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('mayoi-spiral-home','{"id": "mayoi-spiral-home", "character_ko": "하치쿠지 마요이", "character_ja": "八九寺真宵", "name_ko": "나선 귀로", "name_ja": "螺旋帰道", "rarity": 5, "role": "디펜더", "element": "물속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9681, "공격력": 2436, "방어력": 4262, "스피드": 95}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/mayoi-spiral-home-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HE9lIpvagAEb1kj.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "螺旋帰道", "name_ko": "나선 귀로", "ja": "敵全体に300%の水属性ダメージを与える。\n味方全体にクリティカルダメージ+30%(2ターン)。\n自身の魔力+3", "ko": "적 전체에게 300%의 물속성 피해를 준다.\n아군 전체에게 치명타 피해 +30%(2턴).\n자신의 마력 +3.", "cost": "MP 90", "break": 25}, {"kind": "전투 스킬", "name_ja": "無限無軌道", "name_ko": "무한 무궤도", "ja": "味方全体に発動者の防御力64%+405のバリア(3ターン)を付与し、弱点属性に対して与えるダメージ+15%(2ターン)。\n自身に迷宮の魔法少女(2ターン)を付与し、魔力+2。", "ko": "아군 전체에게 발동자 방어력의 64%+405만큼 배리어(3턴)를 부여하고, 약점 속성에 대해 주는 피해 +15%(2턴).\n자신에게 미궁의 마법소녀(2턴)를 부여하고, 마력 +2.", "cost": null, "break": null}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "迷宮の魔法少女", "name_ko": "미궁의 마법소녀", "ja": "MP回復効率+5%、スピード+20%", "ko": "MP 회복 효율 +5%, 스피드 +20%.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の水属性ダメージを与える。\n自身の魔力+1", "ko": "적 하나에게 100%의 물속성 피해를 준다.\n자신의 마력 +1.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "クイックシャープ", "name_ko": "퀵 샤프", "ja": "バトル開始時に魔力0/8、行動順+60%、MP+60。\nバリアが付与されている味方のクリティカル率+15%。\n【自身または味方が攻撃を受けたとき】\n魔力+1。\n【魔力が8になったとき】\n自身の行動順+10%。\n味方全体のHPを発動者のHP5%回復する、魔力-8", "ko": "전투 시작 시 마력 0/8, 행동 순서 +60%, MP +60.\n배리어가 부여된 아군의 치명타 확률 +15%.\n【자신 또는 아군이 공격받았을 때】\n마력 +1.\n【마력이 8이 되었을 때】\n자신의 행동 순서 +10%.\n아군 전체의 HP를 발동자 HP의 5%만큼 회복하고, 마력 -8.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ガードプロヴォーク", "name_ko": "가드 프로보크", "ja": "【ディフェンダーに装備時】\n防御力+10%。\nバリアが付与されているとき狙われる確率上昇", "ko": "【디펜더에게 장착 시】\n방어력 +10%.\n배리어가 부여된 상태일 때 공격 대상이 될 확률 증가.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "その攻撃、迷子にさせていただきます！", "name_ko": "그 공격, 길을 잃게 해드리겠습니다!", "ja": "最大HP+10%、狙われる確率上昇。\n必殺技を発動したときスピード+10%(2ターン)", "ko": "최대 HP +10%, 공격 대상이 될 확률 증가.\n필살기를 발동하면 스피드 +10%(2턴).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵の攻撃で1以上ダメージを受けたときMP+5、バトル開始時に自身にシールドを付与(20%/2回)", "ko": "HP·공격력·방어력 +2%.\n적의 공격으로 1 이상의 피해를 받으면 MP +5. 전투 시작 시 자신에게 실드 부여(20% / 2회)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nバリアが付与されている味方の受けるダメージ-10%。\n戦闘スキルを発動したとき魔力+1、行動順+10%", "ko": "HP·공격력·방어력 +2%.\n배리어가 부여된 아군이 받는 피해 -10%.\n전투 스킬을 발동하면 마력 +1, 행동 순서 +10%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵の攻撃で1以上ダメージを受けたときMP+5。\n味方全体の防御力+20%", "ko": "HP·공격력·방어력 +2%.\n적의 공격으로 1 이상의 피해를 받으면 MP +5.\n아군 전체의 방어력 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('fuuka-final-fate-bloom','{"id": "fuuka-final-fate-bloom", "character_ko": "히구라시 후우카", "character_ja": "日暮ふうか", "name_ko": "파이널 페이트 블룸", "name_ja": "ファイナル・フェイトブルーム", "rarity": 5, "role": "브레이커", "element": "어둠속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9931, "공격력": 3107, "방어력": 3508, "스피드": 114}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/fuuka-final-fate-bloom-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HEZpA96bAAAvy01.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "ファイナル・フェイトブルーム", "name_ko": "파이널 페이트 블룸", "ja": "敵全体に280%の闇属性ダメージを与え、攻撃対象の受けるクリティカル確率+10%(2ターン)。\n自身に深淵の薔薇(2ターン)を付与し、魔力+2。\n【魔力が10のとき】\nSP+1。\n味方アタッカーのMP+10。\n自身が再行動し、魔力-10。\n※魔力は上昇しない", "ko": "적 전체에게 280%의 어둠속성 피해를 주고, 공격 대상이 치명타를 받을 확률 +10%(2턴).\n자신에게 심연의 장미(2턴)를 부여하고, 마력 +2.\n【마력이 10일 때】\nSP +1.\n아군 어태커의 MP +10.\n자신이 재행동하고, 마력 -10.\n※ 마력은 증가하지 않는다.", "cost": "MP 90", "break": 113}, {"kind": "필살기 · 고유 효과", "name_ja": "深淵の薔薇", "name_ko": "심연의 장미", "ja": "スピード+20%、受けるダメージ-10%。", "ko": "스피드 +20%, 받는 피해 -10%.", "cost": null, "break": null}, {"kind": "전투 스킬 · 심연의 장미 없음", "name_ja": "ローズ・スナップ", "name_ko": "로즈 스냅", "ja": "【深淵の薔薇が付与されていないとき】\n敵全体に135%の闇属性ダメージを与える。\n自身の魔力+2。", "ko": "【심연의 장미가 부여되지 않은 상태】\n적 전체에게 135%의 어둠속성 피해를 준다.\n자신의 마력 +2.", "cost": null, "break": 42}, {"kind": "전투 스킬 · 심연의 장미 보유", "name_ja": "ローズ・スマイト", "name_ko": "로즈 스마이트", "ja": "【深淵の薔薇が付与されているとき】\n戦闘スキル発動時に自身のブレイクゲージ削減量上昇。\n敵全体に155%の闇属性ダメージを与える。\n自身のMP+10、魔力+2", "ko": "【심연의 장미가 부여된 상태】\n전투 스킬 발동 시 자신의 브레이크 게이지 감소량 증가.\n적 전체에게 155%의 어둠속성 피해를 준다.\n자신의 MP +10, 마력 +2.", "cost": null, "break": 47}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の闇属性ダメージを与える。\n自身の魔力+1", "ko": "적 하나에게 100%의 어둠속성 피해를 준다.\n자신의 마력 +1.", "cost": null, "break": 24}, {"kind": "어빌리티", "name_ja": "クイックアクセル", "name_ko": "퀵 액셀", "ja": "バトル開始時に魔力6/10、行動順+60%、MP+60。\n【自身または味方が敵に闇属性ダメージを与えたとき】\n敵全体の闇属性耐性-2%(2ターン/累積5回)。\n※通常攻撃/戦闘スキル/必殺技のみ有効", "ko": "전투 시작 시 마력 6/10, 행동 순서 +60%, MP +60.\n【자신 또는 아군이 적에게 어둠속성 피해를 주었을 때】\n적 전체의 어둠속성 내성 -2%(2턴 / 5회 중첩).\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストテクニカル", "name_ko": "헤이스트 테크니컬", "ja": "【ブレイカーに装備時】\nブレイクゲージ削減量上昇、通常攻撃のブレイクボーナス+30%。\n戦闘スキルを発動したとき自身のスピード+25%(2ターン)", "ko": "【브레이커에게 장착 시】\n브레이크 게이지 감소량 증가, 일반 공격의 브레이크 보너스 +30%.\n전투 스킬을 발동하면 자신의 스피드 +25%(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "仕方ないからやりあおう", "name_ko": "어쩔 수 없으니 맞붙자", "ja": "ブレイク削減量上昇、ブレイクボーナス+30%。\n【深淵の薔薇が付与されているとき】\n受けるダメージ-10%", "ko": "브레이크 감소량 증가, 브레이크 보너스 +30%.\n【심연의 장미가 부여된 상태】\n받는 피해 -10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nブレイクゲージ削減量上昇、敵がブレイクしたときスピード+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n브레이크 게이지 감소량 증가. 적이 브레이크되면 스피드 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nバトル開始時に魔力+2。\n通常攻撃で獲得する魔力+1。\n自身が必殺技を発動したとき味方全体の攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n전투 시작 시 마력 +2.\n일반 공격으로 얻는 마력 +1.\n자신이 필살기를 발동하면 아군 전체의 공격력 +20%(2턴)."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたとき味方全体の行動順を+20%", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 아군 전체의 행동 순서 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('sumire-floral-iron-spike','{"id": "sumire-floral-iron-spike", "character_ko": "요아케 스미레", "character_ja": "夜明すみれ", "name_ko": "플로럴 아이언 스파이크", "name_ja": "フローラル・アイアンスパイク", "rarity": 5, "role": "어태커", "element": "나무속성", "limited": true, "acquisition": "한정", "stats": {"HP": 8999, "공격력": 3992, "방어력": 2947, "스피드": 100}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/sumire-floral-iron-spike-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HEZVeiAbsAAe3WT.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "フローラル・アイアンスパイク", "name_ko": "플로럴 아이언 스파이크", "ja": "必殺技発動時に自身のクリティカルダメージ+30%。\n敵全体に320%の木属性ダメージを与える。\n味方ブレイカーのスピード+20%(1ターン)。\nさらに【自身の木属性フィールドが発動中】\n必殺技発動時に自身の必殺技の与えるダメージ+50%、木属性フィールドのストック-3", "ko": "필살기 발동 시 자신의 치명타 피해 +30%.\n적 전체에게 320%의 나무속성 피해를 준다.\n아군 브레이커의 스피드 +20%(1턴).\n추가로 【자신의 나무속성 필드 발동 중】\n필살기 발동 시 자신의 필살기가 주는 피해 +50%, 나무속성 필드의 스톡 -3.", "cost": "MP 150", "break": 25}, {"kind": "전투 스킬 · 필드 미발동", "name_ja": "ヴァイオレット・ワルツ", "name_ko": "바이올렛 왈츠", "ja": "【自身の木属性フィールドが発動していないとき】\n敵全体に180%の木属性ダメージを与える。\n自身に咲き誇る花々(2ターン)を付与する、木属性フィールド(ストック+3)を発動する。", "ko": "【자신의 나무속성 필드가 발동하지 않은 상태】\n적 전체에게 180%의 나무속성 피해를 준다.\n자신에게 만발한 꽃들(2턴)을 부여하고, 나무속성 필드(스톡 +3)를 발동한다.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "咲き誇る花々", "name_ko": "만발한 꽃들", "ja": "自身の受けるダメージ-10%。\n自身以外の味方の攻撃でクリティカルが発生したときスピード+2%(累積10回)。", "ko": "자신이 받는 피해 -10%.\n자신 이외의 아군 공격에서 치명타가 발생하면 스피드 +2%(10회 중첩).", "cost": null, "break": null}, {"kind": "전투 스킬 · 필드", "name_ja": "木属性フィールド", "name_ko": "나무속성 필드", "ja": "味方全体の木属性の与えるダメージ+30%、木属性のクリティカル率+30%。\nストックの最大値は3、発動者が通常攻撃を発動したときストック-1。", "ko": "아군 전체의 나무속성으로 주는 피해 +30%, 나무속성 치명타 확률 +30%.\n스톡의 최대치는 3. 발동자가 일반 공격을 발동하면 스톡 -1.", "cost": null, "break": null}, {"kind": "전투 스킬 · 필드 발동 중", "name_ja": "ヴァイオレット・スイング", "name_ko": "바이올렛 스윙", "ja": "【自身の木属性フィールドが発動中】\n敵全体に200%の木属性ダメージを与える。\n自身に咲き誇る花々(2ターン)を付与する、与えるダメージ+30%(2ターン)、攻撃力+40%(1回)。\nさらに、木属性フィールドのストック+2", "ko": "【자신의 나무속성 필드 발동 중】\n적 전체에게 200%의 나무속성 피해를 준다.\n자신에게 만발한 꽃들(2턴)을 부여하고, 주는 피해 +30%(2턴), 공격력 +40%(1회).\n추가로 나무속성 필드의 스톡 +2.", "cost": null, "break": 12}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の木属性ダメージを与える", "ko": "적 하나에게 100%의 나무속성 피해를 준다.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "アクセルストライク", "name_ko": "액셀 스트라이크", "ja": "自身または味方が敵に木属性ダメージを与えたとき自身のクリティカルダメージ+2%(累積10回)、MP+6。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身の木属性フィールドが発動したとき】\nスピード+50%(1ターン)を付与する", "ko": "자신 또는 아군이 적에게 나무속성 피해를 주면 자신의 치명타 피해 +2%(10회 중첩), MP +6.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신의 나무속성 필드가 발동했을 때】\n스피드 +50%(1턴)를 부여한다.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "アサルトアクセル", "name_ko": "어설트 액셀", "ja": "【アタッカーに装備時】\nクリティカル率+15%、攻撃力+10%。\n自身の攻撃でクリティカルが発生したときMP+5", "ko": "【어태커에게 장착 시】\n치명타 확률 +15%, 공격력 +10%.\n자신의 공격에서 치명타가 발생하면 MP +5.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "…私は、みんなを救いたい", "name_ko": "…나는, 모두를 구하고 싶어", "ja": "クリティカル率+10%。\n【自身の木属性フィールド発動中】\n受けるダメージ-10%、スピード+10%", "ko": "치명타 확률 +10%.\n【자신의 나무속성 필드 발동 중】\n받는 피해 -10%, 스피드 +10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときMP+10%、攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 MP +10%, 공격력 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n戦闘スキルで付与するバフの効果ターン+1。\n【自身の木属性フィールドが解除されたとき】\n自身のスピード+20%(1ターン)", "ko": "HP·공격력·방어력 +2%.\n전투 스킬로 부여하는 버프의 효과 지속 턴 +1.\n【자신의 나무속성 필드가 해제되었을 때】\n자신의 스피드 +20%(1턴)."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵のブレイクボーナスが最大になったとき追加ターンを獲得する", "ko": "HP·공격력·방어력 +2%.\n적의 브레이크 보너스가 최대가 되면 추가 턴을 얻는다."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('yotsugi-exception-rule','{"id": "yotsugi-exception-rule", "character_ko": "오노노키 요츠기", "character_ja": "斧乃木余接", "name_ko": "예외가 더 많은 규칙", "name_ja": "例外のほうが多い規則", "rarity": 5, "role": "브레이커", "element": "나무속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9943, "공격력": 3162, "방어력": 3448, "스피드": 112}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/yotsugi-exception-rule-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HFr5MSvaAAA4ktE.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "例外のほうが多い規則", "name_ko": "예외가 더 많은 규칙", "ja": "敵全体に280%の木属性ダメージを与える。\n味方全体の与える弱点属性ダメージ+20%(2ターン)。\n自身のスピード+40%(2ターン)、魔力+3", "ko": "적 전체에게 280%의 나무속성 피해를 준다.\n아군 전체가 주는 약점 속성 피해 +20%(2턴).\n자신의 스피드 +40%(2턴), 마력 +3.", "cost": "MP 75", "break": 128}, {"kind": "전투 스킬 · 마력 9 이하", "name_ja": "マジカル・ステッキ・ショット", "name_ko": "매지컬 스틱 샷", "ja": "【魔力が9以下のとき】\n敵全体に135%の木属性ダメージを与える。\n自身に人形の魔法少女(2ターン)を付与し、魔力+2", "ko": "【마력이 9 이하일 때】\n적 전체에게 135%의 나무속성 피해를 준다.\n자신에게 인형의 마법소녀(2턴)를 부여하고, 마력 +2.", "cost": null, "break": 57}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "人形の魔法少女", "name_ko": "인형의 마법소녀", "ja": "ブレイクゲージ削減量上昇、ブレイクボーナス+50%。\n自身が攻撃するごとに味方全体の与えるダメージ+3%(累積5回)。", "ko": "브레이크 게이지 감소량 증가, 브레이크 보너스 +50%.\n자신이 공격할 때마다 아군 전체가 주는 피해 +3%(5회 중첩).", "cost": null, "break": null}, {"kind": "전투 스킬 · 마력 10", "name_ja": "マジカル・ステッキ・ラッシュ", "name_ko": "매지컬 스틱 러시", "ja": "【魔力が10のとき】\n戦闘スキル発動時に自身のブレイクゲージ削減量上昇、ブレイクボーナス+100%。\n敵単体に195%の木属性ダメージを与える。\nこの戦闘スキルで消費するSPは0", "ko": "【마력이 10일 때】\n전투 스킬 발동 시 자신의 브레이크 게이지 감소량 증가, 브레이크 보너스 +100%.\n적 하나에게 195%의 나무속성 피해를 준다.\n이 전투 스킬의 소모 SP는 0.", "cost": "SP 0", "break": 73}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の木属性ダメージを与える。\n魔力+1", "ko": "적 하나에게 100%의 나무속성 피해를 준다.\n마력 +1.", "cost": null, "break": 39}, {"kind": "어빌리티", "name_ja": "デュアルヘイスト", "name_ko": "듀얼 헤이스트", "ja": "バトル開始時魔力0/10、ブレイクゲージ削減量上昇、ブレイク特効+180%。\n【魔力が10になったとき】\n追加ターンを獲得する。\n自身が通常攻撃、戦闘スキルで攻撃したとき魔力-10。\n自身が敵に攻撃したときスピード+3%(1ターン/敵の数が多いほど効果値上昇、最大15%)", "ko": "전투 시작 시 마력 0/10, 브레이크 게이지 감소량 증가, 브레이크 특효 +180%.\n【마력이 10이 되었을 때】\n추가 턴을 얻는다.\n자신이 일반 공격 또는 전투 스킬로 공격하면 마력 -10.\n자신이 적을 공격하면 스피드 +3%(1턴 / 적 수가 많을수록 효과 증가, 최대 15%).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストテクニカル", "name_ko": "헤이스트 테크니컬", "ja": "【ブレイカーに装備時】\nブレイクゲージ削減量上昇、ブレイクボーナス+20%。\n必殺技を発動したとき自身のスピード+25%(2ターン)", "ko": "【브레이커에게 장착 시】\n브레이크 게이지 감소량 증가, 브레이크 보너스 +20%.\n필살기를 발동하면 자신의 스피드 +25%(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "一気に蹴散らそうか", "name_ko": "한 번에 쓸어버릴까", "ja": "ブレイクボーナス+5%(敵の数が多いほど効果値上昇、最大25%)。\n敵がブレイクしたときMP+10%", "ko": "브레이크 보너스 +5%(적 수가 많을수록 효과 증가, 최대 25%).\n적이 브레이크되면 MP +10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nブレイクゲージ削減量上昇、敵がブレイクしたときスピード+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n브레이크 게이지 감소량 증가. 적이 브레이크되면 스피드 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nバトル開始時に魔力+5。\n人形の魔法少女の効果ターン+1。\n敵がブレイクしたとき行動順+10%", "ko": "HP·공격력·방어력 +2%.\n전투 시작 시 마력 +5.\n인형의 마법소녀 효과 지속 턴 +1.\n적이 브레이크되면 행동 순서 +10%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたとき味方全体の行動順を+20%", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 아군 전체의 행동 순서 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('tart-final-porte-paradis','{"id": "tart-final-porte-paradis", "character_ko": "타르트 ver.Final", "character_ja": "タルトver.Final", "name_ko": "라 포르트 두 파라디", "name_ja": "ラ・ポルトゥ・ドゥ・パラディ", "rarity": 5, "role": "어태커", "element": "빛속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9043, "공격력": 4014, "방어력": 2909, "스피드": 98}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/tart-final-porte-paradis-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HG-Dy0LasAAo1Um.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "ラ・ポルトゥ・ドゥ・パラディ", "name_ko": "라 포르트 두 파라디", "ja": "敵全体に320%の光属性ダメージを与え、オンブル・エ・リュミエールを発動する。\n自身のオンブル・エ・リュミエールの与えるダメージ+30%(2ターン/チャージが増えるごとに効果が上昇、最大60%)、チャージ+15%。\nさらに【チャージが100%のとき】\n敵全体に100%の光属性ダメージを与える。\n自身のチャージ-50%", "ko": "적 전체에게 320%의 빛속성 피해를 주고, 옹브르 에 뤼미에르를 발동한다.\n자신의 옹브르 에 뤼미에르가 주는 피해 +30%(2턴 / 차지가 증가할수록 효과 증가, 최대 60%), 차지 +15%.\n추가로 【차지가 100%일 때】\n적 전체에게 100%의 빛속성 피해를 준다.\n자신의 차지 -50%.", "cost": "MP 150", "break": 25}, {"kind": "전투 스킬", "name_ja": "トロン・ドゥ・リュミエール", "name_ko": "트롱 드 뤼미에르", "ja": "敵全体に180%の光属性ダメージを与える。\n自身に完璧なるイレギュラー(2ターン)を付与し、与えるダメージ+30%(2ターン)、チャージ+10%。", "ko": "적 전체에게 180%의 빛속성 피해를 준다.\n자신에게 완벽한 이레귤러(2턴)를 부여하고, 주는 피해 +30%(2턴), 차지 +10%.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "完璧なるイレギュラー", "name_ko": "완벽한 이레귤러", "ja": "クリティカル率+10%、防御力+30%。\nMP回復効率+5%(チャージが20%増えるごとに+5%/最大30%)", "ko": "치명타 확률 +10%, 방어력 +30%.\nMP 회복 효율 +5%(차지가 20% 증가할 때마다 +5% / 최대 30%).", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の光属性ダメージを与える。\n自身のチャージ+5%", "ko": "적 하나에게 100%의 빛속성 피해를 준다.\n자신의 차지 +5%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ヘイストアクセル", "name_ko": "헤이스트 액셀", "ja": "バトル開始時にチャージ0%(最大100%)。\n自身以外の味方が敵にダメージを与えたとき自身のチャージ+2%、MP+5。\nさらにその攻撃でクリティカルが発生したとき自身のチャージ+3%。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身のチャージが10%以上のとき】\nスピード+6%(チャージが増えるごとに効果が上昇、最大24%)。\nクリティカル率+7%(チャージが増えるごとに効果が上昇、最大28%)。\nクリティカルダメージ+15%(チャージが増えるごとに効果が上昇、最大60%)。\n【敵がブレイクしたときまたは自身のチャージ50%以上で戦闘スキルを発動したとき】\nオンブル・エ・リュミエールを発動する。", "ko": "전투 시작 시 차지 0%(최대 100%).\n자신 이외의 아군이 적에게 피해를 주면 자신의 차지 +2%, MP +5.\n추가로 그 공격에서 치명타가 발생하면 자신의 차지 +3%.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신의 차지가 10% 이상일 때】\n스피드 +6%(차지가 증가할수록 효과 증가, 최대 24%).\n치명타 확률 +7%(차지가 증가할수록 효과 증가, 최대 28%).\n치명타 피해 +15%(차지가 증가할수록 효과 증가, 최대 60%).\n【적이 브레이크되었을 때 또는 자신의 차지가 50% 이상인 상태에서 전투 스킬을 발동했을 때】\n옹브르 에 뤼미에르를 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 추가 공격", "name_ja": "オンブル・エ・リュミエール", "name_ko": "옹브르 에 뤼미에르", "ja": "敵全体に80%の光属性ダメージを与える。\n自身のMP+5", "ko": "적 전체에게 80%의 빛속성 피해를 준다.\n자신의 MP +5.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "アサルトブラスト", "name_ko": "어설트 블라스트", "ja": "【アタッカーに装備時】\n攻撃力+15%、必殺技の与えるダメージ+10%。\nHP80%以上のときクリティカル率+20%", "ko": "【어태커에게 장착 시】\n공격력 +15%, 필살기가 주는 피해 +10%.\nHP가 80% 이상이면 치명타 확률 +20%.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "私は全てを救ってみせる！", "name_ko": "내가 모든 것을 구해 보이겠어!", "ja": "オンブル・エ・リュミエールを発動したとき攻撃力+5%(累積4回)。\n弱点属性に対して与えるダメージ+10%", "ko": "옹브르 에 뤼미에르를 발동하면 공격력 +5%(4회 중첩).\n약점 속성에 대해 주는 피해 +10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときMP+10%、攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 MP +10%, 공격력 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nバトル開始時にチャージ+20%。\nオンブル・エ・リュミエールの与えるダメージ+30%。\n【チャージが50%未満のとき】\n自身以外の味方が敵にダメージを与えたとき自身のチャージ+2%。\nさらにその攻撃でクリティカルが発生したとき自身のチャージ+2%。\n※通常攻撃/戦闘スキル/必殺技のみ有効", "ko": "HP·공격력·방어력 +2%.\n전투 시작 시 차지 +20%.\n옹브르 에 뤼미에르가 주는 피해 +30%.\n【차지가 50% 미만일 때】\n자신 이외의 아군이 적에게 피해를 주면 자신의 차지 +2%.\n추가로 그 공격에서 치명타가 발생하면 자신의 차지 +2%.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵のブレイクボーナスが最大になったとき追加ターンを獲得する", "ko": "HP·공격력·방어력 +2%.\n적의 브레이크 보너스가 최대가 되면 추가 턴을 얻는다."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('ren-sacred-gift','{"id": "ren-sacred-gift", "character_ko": "이스즈 렌", "character_ja": "五十鈴れん", "name_ko": "세이크리드 기프트", "name_ja": "セイクリッド・ギフト", "rarity": 5, "role": "브레이커", "element": "물속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9766, "공격력": 2851, "방어력": 3206, "스피드": 111}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/ren-sacred-gift-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HGEUyGsaIAAkx9o.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "セイクリッド・ギフト", "name_ko": "세이크리드 기프트", "ja": "敵全体に280%の水属性ダメージを与える。\n自身の行動順+20%。\n【真冬の祝福が付与されているとき】\n必殺技発動時に自身のブレイクゲージ削減量上昇。\n味方全体の必殺技で与えるダメージ+30%(2ターン)", "ko": "적 전체에게 280%의 물속성 피해를 준다.\n자신의 행동 순서 +20%.\n【한겨울의 축복이 부여된 상태】\n필살기 발동 시 자신의 브레이크 게이지 감소량 증가.\n아군 전체의 필살기로 주는 피해 +30%(2턴).", "cost": "MP 75", "break": 113}, {"kind": "전투 스킬", "name_ja": "スノウフレーク・ドリーム", "name_ko": "스노플레이크 드림", "ja": "敵全体に135%の水属性ダメージを与え、攻撃対象に100%の確率で衰弱(2ターン)を付与する。\n自身に真冬の祝福(2ターン)を付与する。", "ko": "적 전체에게 135%의 물속성 피해를 주고, 공격 대상에게 100% 확률로 쇠약(2턴)을 부여한다.\n자신에게 한겨울의 축복(2턴)을 부여한다.", "cost": null, "break": 42}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "真冬の祝福", "name_ko": "한겨울의 축복", "ja": "ブレイクゲージ削減量上昇、ブレイクボーナス+100%。\nHPが50%以上のときブレイクゲージ削減量上昇(残りHPが多いほど効果が上昇)。\nHPが50%以上のときブレイクボーナス+10%(残りHPが多いほど効果が上昇、最大50%)", "ko": "브레이크 게이지 감소량 증가, 브레이크 보너스 +100%.\nHP가 50% 이상이면 브레이크 게이지 감소량 증가(남은 HP가 많을수록 효과 증가).\nHP가 50% 이상이면 브레이크 보너스 +10%(남은 HP가 많을수록 효과 증가, 최대 50%).", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の水属性ダメージを与える", "ko": "적 하나에게 100%의 물속성 피해를 준다.", "cost": null, "break": 24}, {"kind": "어빌리티", "name_ja": "アクセルフラジール", "name_ko": "액셀 프라질", "ja": "HPが50%以上のとき状態異常命中率+25%。\n自身が衰弱状態の敵に対して通常攻撃、戦闘スキルでダメージを与えたときMP+5。\n敵がブレイクしたとき100%の確率で敵全体に衰弱(1ターン)を付与し、自身のブレイクボーナス+30%(2ターン)", "ko": "HP가 50% 이상이면 상태 이상 명중률 +25%.\n자신이 쇠약 상태의 적에게 일반 공격 또는 전투 스킬로 피해를 주면 MP +5.\n적이 브레이크되면 100% 확률로 적 전체에게 쇠약(1턴)을 부여하고, 자신의 브레이크 보너스 +30%(2턴).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストテクニカル", "name_ko": "헤이스트 테크니컬", "ja": "【ブレイカーに装備時】\nスピード+20%。\nHPが50%以上のときブレイクゲージ削減量上昇(残りHPが多いほど効果上昇)", "ko": "【브레이커에게 장착 시】\n스피드 +20%.\nHP가 50% 이상이면 브레이크 게이지 감소량 증가(남은 HP가 많을수록 효과 증가).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "幸せな時間を過ごせますように", "name_ko": "행복한 시간을 보낼 수 있기를", "ja": "受けるダメージ-10%。\nスピード+4%(敵が1体増えるごとに効果が上昇、最大20%)", "ko": "받는 피해 -10%.\n스피드 +4%(적이 1명 늘어날 때마다 효과 증가, 최대 20%).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nブレイクゲージ削減量上昇、敵がブレイクしたときスピード+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n브레이크 게이지 감소량 증가. 적이 브레이크되면 스피드 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n真冬の祝福の効果ターン+1。\n真冬の祝福が付与されているときブレイクゲージ削減量上昇", "ko": "HP·공격력·방어력 +2%.\n한겨울의 축복 효과 지속 턴 +1.\n한겨울의 축복이 부여된 상태일 때 브레이크 게이지 감소량 증가."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたとき味方全体の行動順を+20%", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 아군 전체의 행동 순서 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('rika-snow-dome','{"id": "rika-snow-dome", "character_ko": "아야노 리카", "character_ja": "綾野梨花", "name_ko": "반짝 해피! 스노 돔", "name_ja": "キラハピ！スノードーム", "rarity": 5, "role": "힐러", "element": "불속성", "limited": true, "acquisition": "한정", "stats": {"HP": 10218, "공격력": 2711, "방어력": 3192, "스피드": 110}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/rika-snow-dome-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HGEVK0_aMAA3-Ul.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "キラハピ！スノードーム", "name_ko": "반짝 해피! 스노 돔", "ja": "敵単体に360%の火属性ダメージを与える。\n味方全体のHPを発動者のHP30%+1200回復し、全ての状態異常を解除する。\n味方全体のスピード+15%(2ターン)、必殺技で与えるダメージ+15%(2ターン)", "ko": "적 하나에게 360%의 불속성 피해를 준다.\n아군 전체의 HP를 발동자 HP의 30%+1200만큼 회복하고, 모든 상태 이상을 해제한다.\n아군 전체의 스피드 +15%(2턴), 필살기로 주는 피해 +15%(2턴).", "cost": "MP 100", "break": 35}, {"kind": "전투 스킬", "name_ja": "ゆめかわ！スターショット", "name_ko": "꿈처럼 귀여운! 스타 샷", "ja": "敵単体に180%の火属性ダメージを与える。\n味方全体のHPを発動者のHP12%+400回復し、真冬の幻想を付与する(2ターン)。", "ko": "적 하나에게 180%의 불속성 피해를 준다.\n아군 전체의 HP를 발동자 HP의 12%+400만큼 회복하고, 한겨울의 환상(2턴)을 부여한다.", "cost": null, "break": 20}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "真冬の幻想", "name_ko": "한겨울의 환상", "ja": "HPが50%以上のとき与えるダメージ+10%。\nさらに、HPが80%以上のとき弱点属性に対して与えるダメージ+15%", "ko": "HP가 50% 이상이면 주는 피해 +10%.\n추가로 HP가 80% 이상이면 약점 속성에 대해 주는 피해 +15%.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の火属性ダメージを与える", "ko": "적 하나에게 100%의 불속성 피해를 준다.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ヒールアクセル", "name_ko": "힐 액셀", "ja": "バトル開始時MP+60。\n自身のHP20%以上のダメージを受けたとき行動順+10%。\n【自身または味方が敵から1以上のダメージを受けたとき(1回の攻撃につき最大1回)】\n自身のMP+3。\n【敵がブレイクしたとき】\n味方全体のHPを発動者のHP10%回復し、MP+6", "ko": "전투 시작 시 MP +60.\n자신의 HP 20% 이상의 피해를 받으면 행동 순서 +10%.\n【자신 또는 아군이 적에게 1 이상의 피해를 받았을 때(1회 공격당 최대 1회)】\n자신의 MP +3.\n【적이 브레이크되었을 때】\n아군 전체의 HP를 발동자 HP의 10%만큼 회복하고, MP +6.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "アクセルライズ", "name_ko": "액셀 라이즈", "ja": "【ヒーラーに装備時】\nバトル開始時MP+10。\nMP回復効率+5%、スピード+10", "ko": "【힐러에게 장착 시】\n전투 시작 시 MP +10.\nMP 회복 효율 +5%, 스피드 +10.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "神浜中に魔法で雪を降らせちゃおう！", "name_ko": "카미하마 온 도시에 마법으로 눈을 내리게 하자!", "ja": "受けるダメージ-15%。\n必殺技を発動したときMP+10", "ko": "받는 피해 -15%.\n필살기를 발동하면 MP +10.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nMP回復効率+30%", "ko": "HP·공격력·방어력 +2%.\nMP 회복 효율 +30%."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n必殺技のHP回復量+30%。\n真冬の幻想が付与されている味方全体の攻撃力+20%", "ko": "HP·공격력·방어력 +2%.\n필살기의 HP 회복량 +30%.\n한겨울의 환상이 부여된 아군 전체의 공격력 +20%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n最大HP+10%、必殺技を発動したときSP+1", "ko": "HP·공격력·방어력 +2%.\n최대 HP +10%. 필살기를 발동하면 SP +1."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('melissa-disintegration','{"id": "melissa-disintegration", "character_ko": "멜리사 드 비뇰", "character_ja": "メリッサ・ド・ヴィニョル", "name_ko": "데장테그라시옹", "name_ja": "デサンテグラシオン", "rarity": 5, "role": "디버퍼", "element": "물속성", "limited": false, "acquisition": "통상", "stats": {"HP": 8833, "공격력": 3442, "방어력": 3332, "스피드": 114}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/melissa-disintegration-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HGlK2_CbQAAeoOu.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "デサンテグラシオン", "name_ko": "데장테그라시옹", "ja": "敵単体に300%の水属性ダメージを与え、攻撃対象の防御力-20%(2ターン)、【追撃/反撃】で受けるダメージ+30%(2ターン)、さらにバフ効果を1個解除する。\n【憤怒の衝動が付与されているとき】\nデサンテグラシオンのダメージが330%に上昇し、解除できるバフ効果+1。\n憤怒の衝動を解除する", "ko": "적 하나에게 300%의 물속성 피해를 주고, 공격 대상의 방어력 -20%(2턴), 【추격 / 반격】으로 받는 피해 +30%(2턴). 추가로 버프 효과를 1개 해제한다.\n【분노의 충동이 부여된 상태】\n데장테그라시옹의 피해가 330%로 증가하고, 해제할 수 있는 버프 효과 +1.\n분노의 충동을 해제한다.", "cost": "MP 90", "break": 35}, {"kind": "전투 스킬", "name_ja": "ショック・ドゥ・ネアン", "name_ko": "쇼크 뒤 네앙", "ja": "敵単体に225%の水属性ダメージを与え、攻撃対象に受けるダメージ+20%(2ターン)、さらに水属性から受けるダメージ+15%(2ターン)。\n自身に憤怒の衝動(2ターン)を付与し、魔力+3。", "ko": "적 하나에게 225%의 물속성 피해를 주고, 공격 대상에게 받는 피해 +20%(2턴), 추가로 물속성으로 받는 피해 +15%(2턴).\n자신에게 분노의 충동(2턴)을 부여하고, 마력 +3.", "cost": null, "break": 20}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "憤怒の衝動", "name_ko": "분노의 충동", "ja": "自身または味方が敵に水属性ダメージを与えたときMP+3。\n※通常攻撃/戦闘スキル/必殺技のみ有効", "ko": "자신 또는 아군이 적에게 물속성 피해를 주면 MP +3.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の水属性ダメージを与える。\n自身の魔力+1", "ko": "적 하나에게 100%의 물속성 피해를 준다.\n자신의 마력 +1.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "クラッシュチェイス", "name_ko": "크래시 체이스", "ja": "バトル開始時魔力5/10。\n自身の魔力が10になったとき【追撃】を発動する。\n【自身以外の味方が戦闘スキルでダメージを与えたとき】\n自身の魔力+2。", "ko": "전투 시작 시 마력 5/10.\n자신의 마력이 10이 되면 【추격】을 발동한다.\n【자신 이외의 아군이 전투 스킬로 피해를 주었을 때】\n자신의 마력 +2.", "cost": null, "break": null}, {"kind": "어빌리티 · 추격", "name_ja": "追撃", "name_ko": "추격", "ja": "敵単体に135%の水属性ダメージを与え、攻撃対象の防御力-5%(累積3回)。\n魔力-10", "ko": "적 하나에게 135%의 물속성 피해를 주고, 공격 대상의 방어력 -5%(3회 중첩).\n마력 -10.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ジャマーストリクト", "name_ko": "재머 스트릭트", "ja": "【デバッファーに装備時】\nスピード+10%、デバフ命中率+20%。\n自身の付与するデバフの効果+10%(※行動順減少効果は除く)", "ko": "【디버퍼에게 장착 시】\n스피드 +10%, 디버프 명중률 +20%.\n자신이 부여하는 디버프 효과 +10%(※ 행동 순서 감소 효과 제외).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "許す…ものかッ!!", "name_ko": "용서…할까 보냐!!", "ja": "自身の追撃で与えるダメージ+40%。\n【自身が追撃を発動したとき】\n攻撃対象の全属性耐性-2.5%(累積4回)", "ko": "자신의 추격으로 주는 피해 +40%.\n【자신이 추격을 발동했을 때】\n공격 대상의 모든 속성 내성 -2.5%(4회 중첩).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n付与する状態異常とデバフの効果ターン+1(※行動阻害系状態異常は除く)", "ko": "HP·공격력·방어력 +2%.\n부여하는 상태 이상과 디버프의 효과 지속 턴 +1(※ 행동 방해 계열 상태 이상 제외)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nバトル開始時スピード+20%(1ターン)。\n【自身が追撃を発動したとき】\nスピード+20%(2ターン)。\n【憤怒の衝動が付与されている状態で戦闘スキルを発動したとき】\nMP+10", "ko": "HP·공격력·방어력 +2%.\n전투 시작 시 스피드 +20%(1턴).\n【자신이 추격을 발동했을 때】\n스피드 +20%(2턴).\n【분노의 충동이 부여된 상태에서 전투 스킬을 발동했을 때】\nMP +10."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n付与する状態異常とデバフの効果+30%(※行動順減少効果は除く)", "ko": "HP·공격력·방어력 +2%.\n부여하는 상태 이상과 디버프의 효과 +30%(※ 행동 순서 감소 효과 제외)."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('liz-lombre','{"id": "liz-lombre", "character_ko": "리즈 호크우드", "character_ja": "リズ・ホークウッド", "name_ko": "롱브르", "name_ja": "ロンブル", "rarity": 5, "role": "버퍼", "element": "어둠속성", "limited": false, "acquisition": "통상", "stats": {"HP": 8992, "공격력": 3464, "방어력": 3257, "스피드": 121}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/liz-lombre-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HGlKdbvaUAAf8iH.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "ロンブル", "name_ko": "롱브르", "ja": "敵単体に400%の闇属性ダメージを与える。\n味方全体の必殺技で与えるダメージ+30%(2ターン)、弱点属性に対して与えるダメージ+25%(2ターン)。\n味方アタッカーの攻撃力+30%(1ターン)。\n自身の魔力+3", "ko": "적 하나에게 400%의 어둠속성 피해를 준다.\n아군 전체의 필살기로 주는 피해 +30%(2턴), 약점 속성에 대해 주는 피해 +25%(2턴).\n아군 어태커의 공격력 +30%(1턴).\n자신의 마력 +3.", "cost": "MP 100", "break": 35}, {"kind": "전투 스킬", "name_ja": "スピラル・ノワール", "name_ko": "스피랄 누아르", "ja": "敵単体に225%の闇属性ダメージを与える。\n味方全体の与えるダメージ+15%(2ターン)、スピード+10%(2ターン)。\n自身の魔力+2、行動順+20%", "ko": "적 하나에게 225%의 어둠속성 피해를 준다.\n아군 전체가 주는 피해 +15%(2턴), 스피드 +10%(2턴).\n자신의 마력 +2, 행동 순서 +20%.", "cost": null, "break": 20}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の闇属性ダメージを与える。\n自身の魔力+1、行動順+10%", "ko": "적 하나에게 100%의 어둠속성 피해를 준다.\n자신의 마력 +1, 행동 순서 +10%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "アサルトアクセル", "name_ko": "어설트 액셀", "ja": "バトル開始時魔力0/5、スピード+50%(1ターン)。\n【魔力が5になったとき】\n味方全体の攻撃力+30%(1回)。\n自身の魔力-5。\n【自身以外の味方が敵に闇属性/光属性ダメージを与えたとき】\n自身のMP+2。\n※通常攻撃/戦闘スキル/必殺技のみ有効", "ko": "전투 시작 시 마력 0/5, 스피드 +50%(1턴).\n【마력이 5가 되었을 때】\n아군 전체의 공격력 +30%(1회).\n자신의 마력 -5.\n【자신 이외의 아군이 적에게 어둠속성 / 빛속성 피해를 주었을 때】\n자신의 MP +2.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ブラストクイック", "name_ko": "블라스트 퀵", "ja": "【バッファーに装備時】\nスピード+10。\n自身が必殺技を発動したとき味方全体の必殺技で与えるダメージ+15%(1ターン)。\n自身の最大HP20%以上のダメージを受けたとき行動順+5%", "ko": "【버퍼에게 장착 시】\n스피드 +10.\n자신이 필살기를 발동하면 아군 전체의 필살기로 주는 피해 +15%(1턴).\n자신의 최대 HP 20% 이상의 피해를 받으면 행동 순서 +5%.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "光は決して消させない!!", "name_ko": "빛은 절대로 꺼지게 두지 않아!!", "ja": "MP回復効率+10%。\n【戦闘スキルを発動したとき】\n味方全体の与えるダメージ+20%(2ターン)", "ko": "MP 회복 효율 +10%.\n【전투 스킬을 발동했을 때】\n아군 전체가 주는 피해 +20%(2턴).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n付与するバフの効果ターン+1", "ko": "HP·공격력·방어력 +2%.\n부여하는 버프의 효과 지속 턴 +1."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nバトル開始時MP+30。\n戦闘スキルを発動したとき自身のスピード+3%(累積5回)", "ko": "HP·공격력·방어력 +2%.\n전투 시작 시 MP +30.\n전투 스킬을 발동하면 자신의 스피드 +3%(5회 중첩)."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n付与するバフの効果+50%(※MP回復系/行動順上昇効果は除く)、必殺技を発動したときSP+1", "ko": "HP·공격력·방어력 +2%.\n부여하는 버프의 효과 +50%(※ MP 회복 계열 / 행동 순서 상승 효과 제외). 필살기를 발동하면 SP +1."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('homura-black-magic-suppression','{"id": "homura-black-magic-suppression", "character_ko": "아케미 호무라", "character_ja": "暁美ほむら", "name_ko": "검은 마력에 의한 제압", "name_ja": "黒い魔力による制圧", "rarity": 5, "role": "어태커", "element": "무속성", "limited": true, "acquisition": "한정", "stats": {"HP": 8810, "공격력": 3528, "방어력": 2845, "스피드": 100}, "stats_note": "공식 이미지의 최대 강화 수치입니다. 구체적인 레벨·돌파 조건은 미확인입니다.", "image": "/images/homura-black-magic-suppression-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HGlNO4BaQAAesT9.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다.", "한계돌파 4단계의 치명타 확률 25%는 원본에 + 기호가 보이지 않아 그대로 옮겼습니다. 가산 효과인지 게임 내 확인이 필요합니다."], "skills": [{"kind": "필살기", "name_ja": "黒い魔力による制圧", "name_ko": "검은 마력에 의한 제압", "ja": "敵単体に420%の無属性ダメージを与え、隣接する敵に315%の無属性ダメージを与える。\n攻撃対象からバフ効果を1個解除する。\n自身の戦闘スキルで与えるダメージ+30%(1ターン)。\nさらに【敵全体の刻印の合計数が15以上のとき】\n自身が再行動し、SP+1。\n敵全体の刻印-3", "ko": "적 하나에게 420%의 무속성 피해를 주고, 인접한 적에게 315%의 무속성 피해를 준다.\n공격 대상의 버프 효과를 1개 해제한다.\n자신의 전투 스킬로 주는 피해 +30%(1턴).\n추가로 【적 전체의 각인 합계가 15 이상일 때】\n자신이 재행동하고, SP +1.\n적 전체의 각인 -3.", "cost": "MP 150", "break": 30, "adjacent_break": 20}, {"kind": "전투 스킬", "name_ja": "魔弓の連射", "name_ko": "마궁 연사", "ja": "敵単体に225%の無属性ダメージを与え、隣接する敵に169%の無属性ダメージを与える。\n攻撃対象に【刻印】を付与する。\n自身の与えるダメージ+20%(2ターン)。\nさらに【敵全体の刻印の合計数が9以上のとき】\n自身のMP+10、行動順+10%。\n敵全体の刻印-2", "ko": "적 하나에게 225%의 무속성 피해를 주고, 인접한 적에게 169%의 무속성 피해를 준다.\n공격 대상에게 【각인】을 부여한다.\n자신이 주는 피해 +20%(2턴).\n추가로 【적 전체의 각인 합계가 9 이상일 때】\n자신의 MP +10, 행동 순서 +10%.\n적 전체의 각인 -2.", "cost": null, "break": 15, "adjacent_break": 10}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "刻印", "name_ko": "각인", "ja": "刻印の付与後に増加できる数値は敵1体ごとに最大20。\n刻印が付与された敵に対して通常攻撃、戦闘スキル、必殺技で攻撃した時に刻印+1。\n刻印は重複して付与されない、デバフ解除不可", "ko": "각인 부여 후 증가시킬 수 있는 수치는 적 1명당 최대 20.\n각인이 부여된 적을 일반 공격·전투 스킬·필살기로 공격하면 각인 +1.\n각인은 중복 부여되지 않으며 디버프 해제로 제거할 수 없다.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の無属性ダメージを与える", "ko": "적 하나에게 100%의 무속성 피해를 준다.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "シャープストライク", "name_ko": "샤프 스트라이크", "ja": "バトル開始時に行動順+60%。\n自身の受けるダメージ-10%。\n自身または味方が敵を倒したとき刻印が付与されている敵全体の刻印+2。\nさらに【自身が刻印を付与されている敵に対してダメージを与えたとき】\n自身の与えるクリティカルダメージ+5%(ダメージを与えるごとに効果が上昇、最大25%)、自身のクリティカル率+5%(ダメージを与えるごとに効果が上昇、最大25%)", "ko": "전투 시작 시 행동 순서 +60%.\n자신이 받는 피해 -10%.\n자신 또는 아군이 적을 쓰러뜨리면 각인이 부여된 적 전체의 각인 +2.\n추가로 【자신이 각인이 부여된 적에게 피해를 주었을 때】\n자신이 주는 치명타 피해 +5%(피해를 줄 때마다 효과 증가, 최대 25%), 자신의 치명타 확률 +5%(피해를 줄 때마다 효과 증가, 최대 25%).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ブラストヘイスト", "name_ko": "블라스트 헤이스트", "ja": "【アタッカーに装備時】\n自身の戦闘スキルで与えるダメージ+15%、スピード+15", "ko": "【어태커에게 장착 시】\n자신의 전투 스킬로 주는 피해 +15%, 스피드 +15.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "だから私は、戦い続ける…", "name_ko": "그래서 나는, 계속 싸우겠어…", "ja": "クリティカルダメージ+20%。\n【敵全体の刻印の合計数が10以上のとき】\nスピード+10%", "ko": "치명타 피해 +20%.\n【적 전체의 각인 합계가 10 이상일 때】\n스피드 +10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときMP+10%、攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 MP +10%, 공격력 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nクリティカル率+10%。\n必殺技で与えるダメージ+30%。\n【敵全体の刻印の合計数が10以上のとき】\n攻撃力+10%", "ko": "HP·공격력·방어력 +2%.\n치명타 확률 +10%.\n필살기로 주는 피해 +30%.\n【적 전체의 각인 합계가 10 이상일 때】\n공격력 +10%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\nクリティカル率25%。\n敵全体に刻印を付与する。\nバトル開始時敵全体の刻印+2。\n弱点属性の敵に対して与えるダメージ+30%", "ko": "HP·공격력·방어력 +2%.\n치명타 확률 25%.\n적 전체에게 각인을 부여한다.\n전투 시작 시 적 전체의 각인 +2.\n약점 속성의 적에게 주는 피해 +30%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('kanagi-judgment-light','{"id": "kanagi-judgment-light", "character_ko": "이즈미 카나기", "character_ja": "和泉十七夜", "name_ko": "단죄의 빛", "name_ja": "断罪の光芒", "rarity": 5, "role": "어태커", "element": "무속성", "limited": false, "acquisition": "통상", "stats": {"HP": 8444, "공격력": 3989, "방어력": 2920, "스피드": 96}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/kanagi-judgment-light-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HHs8WF0b0AAKFMH.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "断罪の光芒", "name_ko": "단죄의 빛", "ja": "必殺技発動時に自身のクリティカル率+20%。\n敵単体に500%の無属性ダメージを与える。\nさらに、【追撃】を発動する(チャージは消費しない)", "ko": "필살기 발동 시 자신의 치명타 확률 +20%.\n적 하나에게 500%의 무속성 피해를 준다.\n추가로 【추격】을 발동한다(차지는 소모하지 않는다).", "cost": "MP 90", "break": 35}, {"kind": "전투 스킬", "name_ja": "秩序の閃光", "name_ko": "질서의 섬광", "ja": "敵単体に270%の無属性ダメージを与える。\n自身のクリティカル率+15%(2ターン)、クリティカルダメージ+20%(2ターン)、弱点属性に対して与えるダメージ+10%(2ターン)、チャージ+20%", "ko": "적 하나에게 270%의 무속성 피해를 준다.\n자신의 치명타 확률 +15%(2턴), 치명타 피해 +20%(2턴), 약점 속성에 대해 주는 피해 +10%(2턴), 차지 +20%.", "cost": null, "break": 20}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の無属性ダメージを与える。\n自身のチャージ+10%", "ko": "적 하나에게 100%의 무속성 피해를 준다.\n자신의 차지 +10%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ブラストチェイス", "name_ko": "블라스트 체이스", "ja": "バトル開始時にチャージ0%(最大100%)。\n自身または味方の攻撃でクリティカルが発生したときスピード+4%(累積5回)、攻撃力+5%(累積5回)、チャージ+5%。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n自身のチャージが100%のとき、または敵のブレイクボーナスが最大になったとき【追撃】を発動する。\n※それぞれの条件ごとに【追撃】が発動。", "ko": "전투 시작 시 차지 0%(최대 100%).\n자신 또는 아군 공격에서 치명타가 발생하면 스피드 +4%(5회 중첩), 공격력 +5%(5회 중첩), 차지 +5%.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n자신의 차지가 100%일 때 또는 적의 브레이크 보너스가 최대가 되었을 때 【추격】을 발동한다.\n※ 각 조건마다 【추격】이 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 추격", "name_ja": "追撃", "name_ko": "추격", "ja": "敵単体に135%の無属性ダメージを与える。\n自身の必殺技で与えるダメージ+48%(2ターン)、MP+10。\n自身のチャージが100%のときチャージ-100%", "ko": "적 하나에게 135%의 무속성 피해를 준다.\n자신의 필살기로 주는 피해 +48%(2턴), MP +10.\n자신의 차지가 100%이면 차지 -100%.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ブラストシャープ", "name_ko": "블라스트 샤프", "ja": "【アタッカーに装備時】\nクリティカル率+15%。\n自身が戦闘スキルを発動したとき必殺技で与えるダメージ+5%(累積5回)", "ko": "【어태커에게 장착 시】\n치명타 확률 +15%.\n자신이 전투 스킬을 발동하면 필살기로 주는 피해 +5%(5회 중첩).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "お仕置きの時間だ", "name_ko": "벌을 줄 시간이다", "ja": "クリティカル率+20%。\n自身が必殺技を発動したときスピード+15%(2ターン)", "ko": "치명타 확률 +20%.\n자신이 필살기를 발동하면 스피드 +15%(2턴).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときMP+10%、攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 MP +10%, 공격력 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\nクリティカルダメージ+20%。\n自身が【追撃】を発動したとき攻撃力+10%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n치명타 피해 +20%.\n자신이 【추격】을 발동하면 공격력 +10%(2턴)."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵のブレイクボーナスが最大になったとき追加ターンを獲得する", "ko": "HP·공격력·방어력 +2%.\n적의 브레이크 보너스가 최대가 되면 추가 턴을 얻는다."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('mami-invitation-doppel','{"id": "mami-invitation-doppel", "character_ko": "토모에 마미", "character_ja": "巴マミ", "name_ko": "초대의 도펠", "name_ja": "ご招待のドッペル", "rarity": 5, "role": "브레이커", "element": "빛속성", "limited": false, "acquisition": "통상", "stats": {"HP": 9694, "공격력": 3065, "방어력": 3411, "스피드": 106}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/mami-invitation-doppel-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HIkey1kbcAA_K_f.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "ご招待のドッペル", "name_ko": "초대의 도펠", "ja": "【魔力が8未満のとき】\n敵単体に360%の光属性ダメージを与える。\n自身の行動順+10%、魔力+1。\n【魔力が8のとき】\nブレイクゲージ削減量上昇、ブレイクボーナス+150%。\n敵単体に360%の光属性ダメージを与える。\n自身の行動順+20%、魔力-8。\nさらに味方アタッカーのクリティカルダメージ+30%(2ターン)", "ko": "【마력이 8 미만일 때】\n적 하나에게 360%의 빛속성 피해를 준다.\n자신의 행동 순서 +10%, 마력 +1.\n【마력이 8일 때】\n브레이크 게이지 감소량 증가, 브레이크 보너스 +150%.\n적 하나에게 360%의 빛속성 피해를 준다.\n자신의 행동 순서 +20%, 마력 -8.\n추가로 아군 어태커의 치명타 피해 +30%(2턴).", "cost": "MP 90", "break": 150}, {"kind": "전투 스킬", "name_ja": "スパーロ・リエーヴェ", "name_ko": "스파로 리에베", "ja": "敵単体に195%の光属性ダメージを与える。\n自身のスピード+20%(1ターン)、ブレイクゲージ削減量上昇(2ターン)、MP+8", "ko": "적 하나에게 195%의 빛속성 피해를 준다.\n자신의 스피드 +20%(1턴), 브레이크 게이지 감소량 증가(2턴), MP +8.", "cost": null, "break": 63}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の光属性ダメージを与える。\n自身の魔力+1", "ko": "적 하나에게 100%의 빛속성 피해를 준다.\n자신의 마력 +1.", "cost": null, "break": 24}, {"kind": "어빌리티", "name_ja": "アクセルシャープ", "name_ko": "액셀 샤프", "ja": "バトル開始時に魔力4/8。\n自身または味方が戦闘スキル、必殺技でダメージを与えたとき魔力+1。\n【ブレイク中の敵がいるとき】\n味方全体のクリティカル率+20%。\n【敵がブレイクしたとき】\n魔力+4、MP+30", "ko": "전투 시작 시 마력 4/8.\n자신 또는 아군이 전투 스킬·필살기로 피해를 주면 마력 +1.\n【브레이크 중인 적이 있을 때】\n아군 전체의 치명타 확률 +20%.\n【적이 브레이크되었을 때】\n마력 +4, MP +30.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "シャープテクニカル", "name_ko": "샤프 테크니컬", "ja": "【ブレイカーに装備時】\nブレイクゲージ削減量上昇。\n敵がブレイクしたとき味方全体のクリティカル率+15%(2ターン)", "ko": "【브레이커에게 장착 시】\n브레이크 게이지 감소량 증가.\n적이 브레이크되면 아군 전체의 치명타 확률 +15%(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "私は私の行いから逃げない", "name_ko": "나는 내 행동에서 도망치지 않아", "ja": "戦闘スキルを発動したとき、スピード+5%(累積2回)。\n自身がブレイク中の敵にダメージを与えたとき、MP+5", "ko": "전투 스킬을 발동하면 스피드 +5%(2회 중첩).\n자신이 브레이크 중인 적에게 피해를 주면 MP +5.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nブレイクゲージ削減量上昇、敵がブレイクしたときスピード+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n브레이크 게이지 감소량 증가. 적이 브레이크되면 스피드 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n敵のブレイクボーナスが最大になったとき、魔力+4、MP+30。\n戦闘スキルで付与するバフの効果ターン+1", "ko": "HP·공격력·방어력 +2%.\n적의 브레이크 보너스가 최대가 되면 마력 +4, MP +30.\n전투 스킬로 부여하는 버프의 효과 지속 턴 +1."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたとき味方全体の行動順を+20%", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 아군 전체의 행동 순서 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('homura-kyubey-bomb','{"id": "homura-kyubey-bomb", "character_ko": "아케미 호무라", "character_ja": "暁美ほむら", "name_ko": "큐베 폭탄에 의한 폭파 공격", "name_ja": "キュゥべえボムによる爆破攻撃", "rarity": 5, "role": "디버퍼", "element": "어둠속성", "limited": true, "acquisition": "한정", "stats": {"HP": 9343, "공격력": 3772, "방어력": 3046, "스피드": 123}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/homura-kyubey-bomb-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HJX8NZdb0AA7wFP.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "キュゥべえボムによる爆破攻撃", "name_ko": "큐베 폭탄에 의한 폭파 공격", "ja": "敵全体に300%の闇属性ダメージを与え、攻撃対象にクリティカルを受ける確率+15%(2ターン)、キュゥべえボム(2ターン)を付与する。\n【キュゥべえボムが付与されている敵がいるとき】\n攻撃対象のバフ効果を1個解除し、闇属性から受けるダメージ+15%(2ターン)。\n自身のチャージ+20%", "ko": "적 전체에게 300%의 어둠속성 피해를 주고, 공격 대상에게 치명타를 받을 확률 +15%(2턴), 큐베 폭탄(2턴)을 부여한다.\n【큐베 폭탄이 부여된 적이 있을 때】\n공격 대상의 버프 효과를 1개 해제하고, 어둠속성으로 받는 피해 +15%(2턴).\n자신의 차지 +20%.", "cost": "MP 75", "break": 25}, {"kind": "전투 스킬", "name_ja": "風船爆弾投擲", "name_ko": "풍선 폭탄 투척", "ja": "敵全体に150%の闇属性ダメージを与え、攻撃対象の受けるダメージ+20%(2ターン)。\n自身のチャージ+10%", "ko": "적 전체에게 150%의 어둠속성 피해를 주고, 공격 대상이 받는 피해 +20%(2턴).\n자신의 차지 +10%.", "cost": null, "break": 12}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の闇属性ダメージを与える。\n自身のチャージ+5%", "ko": "적 하나에게 100%의 어둠속성 피해를 준다.\n자신의 차지 +5%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "チェイスチャージ", "name_ko": "체이스 차지", "ja": "バトル開始時にチャージ0%(最大100%)、【追撃】を発動する。\n自身以外の味方が敵にダメージを与えたときチャージ+5%。\nさらにその攻撃が闇属性ダメージだった場合、チャージ+5%。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n自身のチャージが100%になったとき、または敵が倒れたとき【追撃】を発動する。\n※それぞれの条件ごとに【追撃】が発動。", "ko": "전투 시작 시 차지 0%(최대 100%), 【추격】을 발동한다.\n자신 이외의 아군이 적에게 피해를 주면 차지 +5%.\n추가로 그 공격이 어둠속성 피해였다면 차지 +5%.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n자신의 차지가 100%가 되었을 때 또는 적이 쓰러졌을 때 【추격】을 발동한다.\n※ 각 조건마다 【추격】이 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 추격", "name_ja": "追撃", "name_ko": "추격", "ja": "敵全体に60%の闇属性ダメージを与え、攻撃対象に防御力-20%(2ターン)、キュゥべえボム(2ターン)を付与する。\n自身のスピード+8%(2ターン/累積5回)。\nキュゥべえボムが付与されている敵がいるとき、SP+1。\n自身のチャージが100%のときチャージ-100%。", "ko": "적 전체에게 60%의 어둠속성 피해를 주고, 공격 대상에게 방어력 -20%(2턴), 큐베 폭탄(2턴)을 부여한다.\n자신의 스피드 +8%(2턴 / 5회 중첩).\n큐베 폭탄이 부여된 적이 있으면 SP +1.\n자신의 차지가 100%이면 차지 -100%.", "cost": null, "break": null}, {"kind": "어빌리티 · 고유 효과", "name_ja": "キュゥべえボム", "name_ko": "큐베 폭탄", "ja": "スピード-5%、闇属性から受けるダメージ+5%", "ko": "스피드 -5%, 어둠속성으로 받는 피해 +5%.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストイレース", "name_ko": "헤이스트 이레이스", "ja": "【デバッファー装備時に発動】\nバトル開始時に行動順+10%。\nスピード+12%。\n自身が必殺技を発動したとき攻撃対象の全属性耐性-5%(2ターン)", "ko": "【디버퍼에게 장착 시 발동】\n전투 시작 시 행동 순서 +10%.\n스피드 +12%.\n자신이 필살기를 발동하면 공격 대상의 모든 속성 내성 -5%(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "揉め事は島の外でやってもらえないかしら？", "name_ko": "다툼은 섬 밖에서 해주지 않겠어?", "ja": "キュゥべえボムが付与されている敵がいるときスピード+10%。\n自身の追撃を発動したときMP+5", "ko": "큐베 폭탄이 부여된 적이 있으면 스피드 +10%.\n자신의 추격을 발동하면 MP +5.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n付与する状態異常とデバフの効果ターン+1(※行動阻害系状態異常は除く)", "ko": "HP·공격력·방어력 +2%.\n부여하는 상태 이상과 디버프의 효과 지속 턴 +1(※ 행동 방해 계열 상태 이상 제외)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n自身が【追撃】を発動したとき攻撃対象に付与されているデバフの効果ターン+1。(延長は最大3ターンまで)\nキュゥべえボムが付与されている敵の全属性耐性-20%", "ko": "HP·공격력·방어력 +2%.\n자신이 【추격】을 발동하면 공격 대상에게 부여된 디버프의 효과 지속 턴 +1(연장은 최대 3턴까지).\n큐베 폭탄이 부여된 적의 모든 속성 내성 -20%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n付与する状態異常とデバフの効果+30%(※行動順減少効果は除く)", "ko": "HP·공격력·방어력 +2%.\n부여하는 상태 이상과 디버프의 효과 +30%(※ 행동 순서 감소 효과 제외)."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('kyoko-summer-fire-attack','{"id": "kyoko-summer-fire-attack", "character_ko": "사쿠라 쿄코", "character_ja": "佐倉杏子", "name_ko": "한여름의 파이어 어택!", "name_ja": "真夏のファイヤーアタック！", "rarity": 5, "role": "버퍼", "element": "불속성", "limited": true, "acquisition": "한정", "stats": {"HP": 10000, "공격력": 3167, "방어력": 3424, "스피드": 121}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/kyoko-summer-fire-attack-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HK0O6qabEAAK_2z.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "真夏のファイヤーアタック！", "name_ko": "한여름의 파이어 어택!", "ja": "敵全体に300%の火属性ダメージを与える。\n味方全体の与えるダメージ+40%(2ターン)。\n自身のMP+15。\n【チャージが100%のとき】\n味方アタッカーのMP+30%、弱点属性に対して与えるダメージ+50%(2ターン)。\n自身、味方アタッカーに追加ダメージ(50%/2ターン)を付与する。\n自身のチャージ-100%", "ko": "적 전체에게 300%의 불속성 피해를 준다.\n아군 전체가 주는 피해 +40%(2턴).\n자신의 MP +15.\n【차지가 100%일 때】\n아군 어태커의 MP +30%, 약점 속성에 대해 주는 피해 +50%(2턴).\n자신과 아군 어태커에게 추가 피해(50% / 2턴)를 부여한다.\n자신의 차지 -100%.", "cost": "MP 75", "break": 25}, {"kind": "전투 스킬", "name_ja": "潮騒の旋風", "name_ko": "파도 소리의 선풍", "ja": "敵全体に150%の火属性ダメージを与える。\n自身、味方アタッカーに激励のビーチボール(2ターン)を付与する。\n自身の行動順+10%、チャージ+10%。", "ko": "적 전체에게 150%의 불속성 피해를 준다.\n자신과 아군 어태커에게 격려의 비치볼(2턴)을 부여한다.\n자신의 행동 순서 +10%, 차지 +10%.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "激励のビーチボール", "name_ko": "격려의 비치볼", "ja": "スピード+2%(敵の数が多いほど効果値上昇、最大10%)、攻撃力+50%、追加ダメージ(40%)、受けるダメージ-10%", "ko": "스피드 +2%(적 수가 많을수록 효과 증가, 최대 10%), 공격력 +50%, 추가 피해(40%), 받는 피해 -10%.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の火属性ダメージを与える。\n自身のチャージ+5%", "ko": "적 하나에게 100%의 불속성 피해를 준다.\n자신의 차지 +5%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ヘイスト", "name_ko": "헤이스트", "ja": "バトル開始時にチャージ0%(最大100%)、味方全体のスピード+20%。\n自身以外の味方が戦闘スキルで敵にダメージを与えたときチャージ+10%。\nその攻撃がアタッカーの攻撃だったとき、さらにチャージ+10%。\n自身または味方がブレイク中の敵を攻撃したときチャージ+5%", "ko": "전투 시작 시 차지 0%(최대 100%), 아군 전체의 스피드 +20%.\n자신 이외의 아군이 전투 스킬로 적에게 피해를 주면 차지 +10%.\n그 공격이 어태커의 공격이면 추가로 차지 +10%.\n자신 또는 아군이 브레이크 중인 적을 공격하면 차지 +5%.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストアクセル", "name_ko": "헤이스트 액셀", "ja": "【バッファーに装備時】\n味方全体のスピード+5%、与えるダメージ+8%。\n自身が戦闘スキルで敵にダメージを与えたとき味方アタッカーのMP+2", "ko": "【버퍼에게 장착 시】\n아군 전체의 스피드 +5%, 주는 피해 +8%.\n자신이 전투 스킬로 적에게 피해를 주면 아군 어태커의 MP +2.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "グアバだ！なかなかいけるぞ！", "name_ko": "구아바다! 꽤 맛있는데!", "ja": "自身に激励のビーチボールが付与されている状態で自身が必殺技を発動したときMP+3。\n激励のビーチボールが付与されている自身と味方アタッカーの受けるダメージ-5%", "ko": "자신에게 격려의 비치볼이 부여된 상태에서 자신이 필살기를 발동하면 MP +3.\n격려의 비치볼이 부여된 자신과 아군 어태커가 받는 피해 -5%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n付与するバフの効果ターン+1", "ko": "HP·공격력·방어력 +2%.\n부여하는 버프의 효과 지속 턴 +1."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときチャージ+20%。\n通常攻撃を発動したとき、味方全体に付与されているバフ効果のターン+1(自身が戦闘スキルおよび必殺技で付与したバフ効果のみが対象/最大3ターン)。\n【自身のチャージが50%以上で自身の戦闘スキルを発動したとき】\n自身以外の味方全体の行動順+5%", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 차지 +20%.\n일반 공격을 발동하면 아군 전체에게 부여된 버프 효과의 지속 턴 +1(자신의 전투 스킬 및 필살기로 부여한 버프 효과만 대상 / 최대 3턴).\n【자신의 차지가 50% 이상인 상태에서 자신의 전투 스킬을 발동했을 때】\n자신 이외의 아군 전체의 행동 순서 +5%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n付与するバフの効果+50%(※MP回復系/行動順上昇効果は除く)、必殺技を発動したときSP+1", "ko": "HP·공격력·방어력 +2%.\n부여하는 버프의 효과 +50%(※ MP 회복 계열 / 행동 순서 상승 효과 제외). 필살기를 발동하면 SP +1."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('iroha-evoluzione-presente','{"id": "iroha-evoluzione-presente", "character_ko": "타마키 이로하", "character_ja": "環いろは", "name_ko": "에볼루치오네 프레젠테", "name_ja": "エヴォルツィオーネ・プレゼンテ", "rarity": 5, "role": "어태커", "element": "물속성", "limited": true, "acquisition": "한정", "stats": {"HP": 8942, "공격력": 3994, "방어력": 2964, "스피드": 102}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/iroha-evoluzione-presente-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HLtJ8PtaoAEivRq.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "エヴォルツィオーネ・プレゼンテ", "name_ko": "에볼루치오네 프레젠테", "ja": "必殺技発動時に自身のクリティカル率+20%。\n敵全体に320%の水属性ダメージを与える。\n自身と味方ブレイカーのスピード+10%(2ターン)。\n【マジカルフロートが付与されているとき】\n自身のMP+30、自身と味方ブレイカーが与えるダメージ+30%(2ターン)", "ko": "필살기 발동 시 자신의 치명타 확률 +20%.\n적 전체에게 320%의 물속성 피해를 준다.\n자신과 아군 브레이커의 스피드 +10%(2턴).\n【매지컬 플로트가 부여된 상태】\n자신의 MP +30. 자신과 아군 브레이커가 주는 피해 +30%(2턴).", "cost": "MP 150", "break": 25}, {"kind": "전투 스킬", "name_ja": "フレッチェ・マリーナ", "name_ko": "프레체 마리나", "ja": "敵全体に180%の水属性ダメージを与える。\n自身のクリティカルダメージ+20%(2ターン)、マジカルフロート(2ターン)を付与する。", "ko": "적 전체에게 180%의 물속성 피해를 준다.\n자신의 치명타 피해 +20%(2턴), 매지컬 플로트(2턴)를 부여한다.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "マジカルフロート", "name_ko": "매지컬 플로트", "ja": "自身の防御力+30%、クリティカル率+20%、スピード+10%", "ko": "자신의 방어력 +30%, 치명타 확률 +20%, 스피드 +10%.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の水属性ダメージを与える", "ko": "적 하나에게 100%의 물속성 피해를 준다.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ストライクチェイス", "name_ko": "스트라이크 체이스", "ja": "自身または味方が敵に水属性ダメージを与えたとき自身のクリティカルダメージ+2%(累積10回)、MP+6。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身または味方ブレイカーが必殺技を発動したとき】\n【追撃】を発動する。\n※それぞれの条件ごとに【追撃】が発動。", "ko": "자신 또는 아군이 적에게 물속성 피해를 주면 자신의 치명타 피해 +2%(10회 중첩), MP +6.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신 또는 아군 브레이커가 필살기를 발동했을 때】\n【추격】을 발동한다.\n※ 각 조건마다 【추격】이 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 추격", "name_ja": "追撃", "name_ko": "추격", "ja": "敵全体に60%の水属性ダメージを与える。\n自身の攻撃力+5%(累積5回)、弱点属性に対して与えるダメージ+5%(累積5回)。\nさらに【自身の水属性フィールドが発動していないとき】\n自身の水属性フィールド(ストック+3)を発動する。", "ko": "적 전체에게 60%의 물속성 피해를 준다.\n자신의 공격력 +5%(5회 중첩), 약점 속성에 대해 주는 피해 +5%(5회 중첩).\n추가로 【자신의 물속성 필드가 발동하지 않은 상태】\n자신의 물속성 필드(스톡 +3)를 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 필드", "name_ja": "水属性フィールド", "name_ko": "물속성 필드", "ja": "味方全体の水属性の与えるダメージ+30%、水属性のクリティカル率+30%。\nストックの最大値は3、発動者が【追撃】を発動したときストック+1、通常攻撃を発動したときストック-1", "ko": "아군 전체의 물속성으로 주는 피해 +30%, 물속성 치명타 확률 +30%.\n스톡의 최대치는 3. 발동자가 【추격】을 발동하면 스톡 +1, 일반 공격을 발동하면 스톡 -1.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストシャープ", "name_ko": "헤이스트 샤프", "ja": "【アタッカーに装備時】\nクリティカル率+10%、スピード+10%。\n戦闘スキルまたは必殺技を発動したとき、弱点属性に対して与えるダメージ+10%(累積2回/2ターン)", "ko": "【어태커에게 장착 시】\n치명타 확률 +10%, 스피드 +10%.\n전투 스킬 또는 필살기를 발동하면 약점 속성에 대해 주는 피해 +10%(2회 중첩 / 2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "やった！自己新記録達成！", "name_ko": "해냈다! 개인 신기록 달성!", "ja": "自身が【追撃】を発動したとき、クリティカルダメージ+10%(2ターン)、スピード+10%(2ターン)", "ko": "자신이 【추격】을 발동하면 치명타 피해 +10%(2턴), 스피드 +10%(2턴).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたときMP+10%、攻撃力+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 MP +10%, 공격력 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n【追撃】で与えるダメージ+15%。\n【マジカルフロートが付与されているとき】\n戦闘スキル、【追撃】のクリティカル率+20%", "ko": "HP·공격력·방어력 +2%.\n【추격】으로 주는 피해 +15%.\n【매지컬 플로트가 부여된 상태】\n전투 스킬·【추격】의 치명타 확률 +20%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵のブレイクボーナスが最大になったとき追加ターンを獲得する", "ko": "HP·공격력·방어력 +2%.\n적의 브레이크 보너스가 최대가 되면 추가 턴을 얻는다."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('yachiyo-absolute-venus','{"id": "yachiyo-absolute-venus", "character_ko": "나나미 야치요", "character_ja": "七海やちよ", "name_ko": "앱솔루트 비너스", "name_ja": "アブソリュート・ヴィーナス", "rarity": 5, "role": "브레이커", "element": "물속성", "limited": true, "acquisition": "한정", "stats": {"HP": 10045, "공격력": 3070, "방어력": 3508, "스피드": 114}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/yachiyo-absolute-venus-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HNGYxztacAEUG1E.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "アブソリュート・ヴィーナス", "name_ko": "앱솔루트 비너스", "ja": "敵全体に280%の水属性ダメージを与え、攻撃対象の水属性耐性-2%(2ターン/累積5回)。\n【潮騒の熱視線が付与されているとき】\n味方全体のクリティカルダメージ+20%(2ターン)。\nさらに【自身の魔力が10以上の状態で潮騒の熱視線が付与されているとき】\n自身のスピード+30%(2ターン)", "ko": "적 전체에게 280%의 물속성 피해를 주고, 공격 대상의 물속성 내성 -2%(2턴 / 5회 중첩).\n【파도 소리의 뜨거운 시선이 부여된 상태】\n아군 전체의 치명타 피해 +20%(2턴).\n추가로 【자신의 마력이 10 이상이며 파도 소리의 뜨거운 시선이 부여된 상태】\n자신의 스피드 +30%(2턴).", "cost": "MP 75", "break": 133}, {"kind": "전투 스킬", "name_ja": "セルリアン・カスケード", "name_ko": "세룰리안 캐스케이드", "ja": "敵全体に135%の水属性ダメージを与える。\n味方全体に潮騒の熱視線(2ターン)を付与する。\n【自身の魔力が20のとき】\nこの戦闘スキルで消費するSPは0。\n自身の魔力-10", "ko": "적 전체에게 135%의 물속성 피해를 준다.\n아군 전체에게 파도 소리의 뜨거운 시선(2턴)을 부여한다.\n【자신의 마력이 20일 때】\n이 전투 스킬의 소모 SP는 0.\n자신의 마력 -10.", "cost": null, "break": 62}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "潮騒の熱視線", "name_ko": "파도 소리의 뜨거운 시선", "ja": "クリティカル率+10%。\n対象が水属性のとき、さらにクリティカル率+5%。", "ko": "치명타 확률 +10%.\n대상이 물속성이면 추가로 치명타 확률 +5%.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の水属性ダメージを与える", "ko": "적 하나에게 100%의 물속성 피해를 준다.", "cost": null, "break": 32}, {"kind": "어빌리티", "name_ja": "ヘイストテクニカル", "name_ko": "헤이스트 테크니컬", "ja": "自身または味方が敵に水属性ダメージを与えたときMP+3。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n自身の魔力が20で戦闘スキルを発動したとき、または敵が倒れたとき【追撃】を発動する。\n※それぞれの条件ごとに【追撃】が発動。\nバトル開始時に魔力0/20、スピード+50%(2ターン)、ブレイクゲージ削減量上昇。\n自身が戦闘スキルを発動したとき魔力+2。\n自身が通常攻撃を発動したとき魔力+1。\n自身以外の味方がダメージを与えたとき魔力+1。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身の魔力が2以上のとき】\n自身のスピード+4%(魔力が2増えるごとに効果が上昇、最大20%)。\n自身のブレイクボーナス+20%(魔力が2増えるごとに効果が上昇、最大100%)", "ko": "자신 또는 아군이 적에게 물속성 피해를 주면 MP +3.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n자신의 마력이 20인 상태에서 전투 스킬을 발동했을 때 또는 적이 쓰러졌을 때 【추격】을 발동한다.\n※ 각 조건마다 【추격】이 발동한다.\n전투 시작 시 마력 0/20, 스피드 +50%(2턴), 브레이크 게이지 감소량 증가.\n자신이 전투 스킬을 발동하면 마력 +2.\n자신이 일반 공격을 발동하면 마력 +1.\n자신 이외의 아군이 피해를 주면 마력 +1.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신의 마력이 2 이상일 때】\n자신의 스피드 +4%(마력이 2 증가할 때마다 효과 증가, 최대 20%).\n자신의 브레이크 보너스 +20%(마력이 2 증가할 때마다 효과 증가, 최대 100%).", "cost": null, "break": null}, {"kind": "어빌리티 · 추격", "name_ja": "追撃", "name_ko": "추격", "ja": "敵全体に75%の水属性ダメージを与える。\n攻撃対象にブレイク中に水属性から受けるダメージ+10%(2ターン)。", "ko": "적 전체에게 75%의 물속성 피해를 준다.\n공격 대상에게 브레이크 중 물속성으로 받는 피해 +10%(2턴).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストテクニカル", "name_ko": "헤이스트 테크니컬", "ja": "【ブレイカーに装備時】\nスピード+20%、クリティカル率+10%。\n自身の攻撃でクリティカルが発生したときブレイクゲージ削減量上昇(2ターン)", "ko": "【브레이커에게 장착 시】\n스피드 +20%, 치명타 확률 +10%.\n자신의 공격에서 치명타가 발생하면 브레이크 게이지 감소량 증가(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "もっと深く、長く泳げるように…！", "name_ko": "더 깊이, 오래 헤엄칠 수 있도록…!", "ja": "【潮騒の熱視線が付与されているとき】\n受けるダメージ-10%。\n【敵がブレイクしたとき】\nスピード+10%(1ターン)", "ko": "【파도 소리의 뜨거운 시선이 부여된 상태】\n받는 피해 -10%.\n【적이 브레이크되었을 때】\n스피드 +10%(1턴).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nブレイクゲージ削減量上昇、敵がブレイクしたときスピード+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n브레이크 게이지 감소량 증가. 적이 브레이크되면 스피드 +20%(2턴)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n潮騒の熱視線の効果ターン+1。\n【敵がブレイクしたとき】\n味方全体の必殺技で与えるダメージ+20%(2ターン)", "ko": "HP·공격력·방어력 +2%.\n파도 소리의 뜨거운 시선 효과 지속 턴 +1.\n【적이 브레이크되었을 때】\n아군 전체의 필살기로 주는 피해 +20%(2턴)."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵がブレイクしたとき味方全体の行動順を+20%", "ko": "HP·공격력·방어력 +2%.\n적이 브레이크되면 아군 전체의 행동 순서 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('sayaka-grandioso-sinfonia','{"id": "sayaka-grandioso-sinfonia", "character_ko": "미키 사야카", "character_ja": "美樹さやか", "name_ko": "그란디오소 신포니아", "name_ja": "グランディオーソ・シンフォニア", "rarity": 5, "role": "힐러", "element": "물속성", "limited": true, "acquisition": "한정", "stats": {"HP": 11402, "공격력": 3563, "방어력": 3629, "스피드": 110}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/sayaka-grandioso-sinfonia-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HOdh_lSbsAE_yp9.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "グランディオーソ・シンフォニア", "name_ko": "그란디오소 신포니아", "ja": "敵全体に280%の水属性ダメージを与える。\n味方全体のHPを発動者の攻撃力60%+1500回復し、状態異常を全て解除する。\n味方全体のクリティカルダメージ+15%(2ターン)。\nさらに【魔力8のとき】\n味方全体のスピード+10%(2ターン)、水属性で与えるダメージ+10%(2ターン)。\n自身の魔力-8", "ko": "적 전체에게 280%의 물속성 피해를 준다.\n아군 전체의 HP를 발동자 공격력의 60%+1500만큼 회복하고, 상태 이상을 모두 해제한다.\n아군 전체의 치명타 피해 +15%(2턴).\n추가로 【마력이 8일 때】\n아군 전체의 스피드 +10%(2턴), 물속성으로 주는 피해 +10%(2턴).\n자신의 마력 -8.", "cost": "MP 90", "break": 25}, {"kind": "전투 스킬", "name_ja": "アルペジオ・レガート", "name_ko": "아르페지오 레가토", "ja": "敵全体に135%の水属性ダメージを与える。\n味方全体のHPを発動者の攻撃力25%+450回復し、クレッシェンド(2ターン)、リゲイン(攻撃力8%/2ターン)を付与する。\n自身の魔力+2。", "ko": "적 전체에게 135%의 물속성 피해를 준다.\n아군 전체의 HP를 발동자 공격력의 25%+450만큼 회복하고, 크레셴도(2턴), 리게인(공격력 8% / 2턴)을 부여한다.\n자신의 마력 +2.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "クレッシェンド", "name_ko": "크레셴도", "ja": "HP回復量+20%。\nHP回復効果を受けたとき攻撃力+5%(累積5回)、クリティカル率+5%(累積3回)。\n※通常攻撃/戦闘スキル/必殺技/追撃/反撃/援護で発動した回復効果のみ有効", "ko": "HP 회복량 +20%.\nHP 회복 효과를 받으면 공격력 +5%(5회 중첩), 치명타 확률 +5%(3회 중첩).\n※ 일반 공격 / 전투 스킬 / 필살기 / 추격 / 반격 / 지원으로 발동한 회복 효과에만 유효.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の水属性ダメージを与える。\n自身の魔力+1", "ko": "적 하나에게 100%의 물속성 피해를 준다.\n자신의 마력 +1.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "アサルトヘイスト", "name_ko": "어설트 헤이스트", "ja": "バトル開始時に魔力0/8、攻撃力+20%。\n自身以外の味方が敵にダメージを与えたとき魔力+1。\nさらにその攻撃が水属性ダメージだった場合、魔力+1。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身のHPが50%以上のとき】\nスピード+15%。\n【敵がブレイクしたとき】\n自身のMP+10", "ko": "전투 시작 시 마력 0/8, 공격력 +20%.\n자신 이외의 아군이 적에게 피해를 주면 마력 +1.\n추가로 그 공격이 물속성 피해였다면 마력 +1.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신의 HP가 50% 이상일 때】\n스피드 +15%.\n【적이 브레이크되었을 때】\n자신의 MP +10.", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ヘイストシャープ", "name_ko": "헤이스트 샤프", "ja": "【ヒーラーに装備時】\nスピード+12%。\n敵にダメージを与えたときクリティカル率+5%(2ターン/累積3回)", "ko": "【힐러에게 장착 시】\n스피드 +12%.\n적에게 피해를 주면 치명타 확률 +5%(2턴 / 3회 중첩).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "こんな穏やかな日常に、感謝しないと", "name_ko": "이렇게 평온한 일상에 감사해야지", "ja": "必殺技を発動したとき味方全体のクリティカル率+10%(2ターン)。\n【クレッシェンドが付与されているとき】\n防御力+20%", "ko": "필살기를 발동하면 아군 전체의 치명타 확률 +10%(2턴).\n【크레셴도가 부여된 상태】\n방어력 +20%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\nMP回復効率+30%", "ko": "HP·공격력·방어력 +2%.\nMP 회복 효율 +30%."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n自身が付与するリゲイン、クレッシェンドの効果ターン+1。\n自身がHP回復効果を受けたとき味方全体のクリティカルダメージ+10%(2ターン)。\n※通常攻撃/戦闘スキル/必殺技/追撃/反撃/援護で発動した回復効果のみ有効", "ko": "HP·공격력·방어력 +2%.\n자신이 부여하는 리게인·크레셴도의 효과 지속 턴 +1.\n자신이 HP 회복 효과를 받으면 아군 전체의 치명타 피해 +10%(2턴).\n※ 일반 공격 / 전투 스킬 / 필살기 / 추격 / 반격 / 지원으로 발동한 회복 효과에만 유효."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n最大HP+10%、必殺技を発動したときSP+1", "ko": "HP·공격력·방어력 +2%.\n최대 HP +10%. 필살기를 발동하면 SP +1."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
INSERT INTO memories (id,payload,published) VALUES ('mami-spietata-scarica','{"id": "mami-spietata-scarica", "character_ko": "토모에 마미", "character_ja": "巴マミ", "name_ko": "스피에타타 스카리카", "name_ja": "スピエタータ・スカーリカ", "rarity": 5, "role": "디펜더", "element": "나무속성", "limited": true, "acquisition": "한정", "stats": {"HP": 10351, "공격력": 2937, "방어력": 4624, "스피드": 96}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/mami-spietata-scarica-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HOdjph9bwAAIQWu.jpeg). 공식 게시물 URL과 게시일 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["고유명사는 임시 한국어 표기이며, 일본어 원문을 함께 보존합니다.", "스킬 효과는 최대 강화 표기 기준입니다. 이미지에 없는 소모 SP와 지속 시간·증가량은 추정하지 않았습니다."], "skills": [{"kind": "필살기", "name_ja": "スピエタータ・スカーリカ", "name_ko": "스피에타타 스카리카", "ja": "敵単体に400%の木属性ダメージを与える。\n味方全体のデバフ効果を1個解除し、受けるダメージ-20%(2ターン)。\n付与対象が木属性のとき、さらに受けるダメージ-10%(2ターン)。\nさらに【自身のチャージが100%のとき】\n味方全体のクリティカルダメージ+10%(2ターン)。\n付与対象が木属性のとき、さらにクリティカルダメージ+10%(2ターン)。\n自身のチャージ-50%", "ko": "적 하나에게 400%의 나무속성 피해를 준다.\n아군 전체의 디버프 효과를 1개 해제하고, 받는 피해 -20%(2턴).\n부여 대상이 나무속성이면 추가로 받는 피해 -10%(2턴).\n추가로 【자신의 차지가 100%일 때】\n아군 전체의 치명타 피해 +10%(2턴).\n부여 대상이 나무속성이면 추가로 치명타 피해 +10%(2턴).\n자신의 차지 -50%.", "cost": "MP 75", "break": 35}, {"kind": "전투 스킬", "name_ja": "ティロ・テンペスタ", "name_ko": "티로 템페스타", "ja": "敵単体に225%の木属性ダメージを与える。\n味方全体に勝利の号砲(2ターン)、発動者の防御力77%+486のバリア(2ターン)を付与する。\n自身のスピード+25%(2ターン)、チャージ+10%。", "ko": "적 하나에게 225%의 나무속성 피해를 준다.\n아군 전체에게 승리의 예포(2턴), 발동자 방어력의 77%+486만큼 배리어(2턴)를 부여한다.\n자신의 스피드 +25%(2턴), 차지 +10%.", "cost": null, "break": 20}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "勝利の号砲", "name_ko": "승리의 예포", "ja": "防御力+20%。\n付与対象がダメージを与えたとき、クリティカル率+3%(累積5回)", "ko": "방어력 +20%.\n부여 대상이 피해를 주면 치명타 확률 +3%(5회 중첩).", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の木属性ダメージを与える", "ko": "적 하나에게 100%의 나무속성 피해를 준다.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "アサルトライズ", "name_ko": "어설트 라이즈", "ja": "バリアが付与されている味方全体の攻撃力+15%。\nバトル開始時にチャージ0%(最大100%)、スピード+50%(1ターン)。\n自身または味方が敵にダメージを与えたとき自身のチャージ+5%。\nさらにその攻撃でクリティカルが発生したとき自身のチャージ+5%。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身のチャージが10%以上のとき】\n自身のMP回復効率+4%(チャージが10%増えるごとに効果が上昇、最大20%)", "ko": "배리어가 부여된 아군 전체의 공격력 +15%.\n전투 시작 시 차지 0%(최대 100%), 스피드 +50%(1턴).\n자신 또는 아군이 적에게 피해를 주면 자신의 차지 +5%.\n추가로 그 공격에서 치명타가 발생하면 자신의 차지 +5%.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신의 차지가 10% 이상일 때】\n자신의 MP 회복 효율 +4%(차지가 10% 증가할 때마다 효과 증가, 최대 20%).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "ディフェンドヘイスト", "name_ko": "디펜드 헤이스트", "ja": "【ディフェンダーに装備時】\n最大HP+12%、スピード+10。\n自身が必殺技を発動したとき味方全体の受けるダメージ-5%(2ターン)", "ko": "【디펜더에게 장착 시】\n최대 HP +12%, 스피드 +10.\n자신이 필살기를 발동하면 아군 전체가 받는 피해 -5%(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "大丈夫、私には仲間がいるもの", "name_ko": "괜찮아, 내게는 동료가 있으니까", "ja": "バトル開始時にチャージ+20%。\n狙われる確率上昇。\n自身が敵の攻撃を受けたときスピード+2%(1ターン/累積5回)", "ko": "전투 시작 시 차지 +20%.\n공격 대상이 될 확률 증가.\n자신이 적의 공격을 받으면 스피드 +2%(1턴 / 5회 중첩).", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n敵の攻撃で1以上ダメージを受けたときMP+5、バトル開始時に自身にシールドを付与(20%/2回)", "ko": "HP·공격력·방어력 +2%.\n적의 공격으로 1 이상의 피해를 받으면 MP +5. 전투 시작 시 자신에게 실드 부여(20% / 2회)."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n必殺技発動時に味方全体から解除できるデバフ効果+1。\nバリアが付与されている味方全体に弱点属性に対して与えるダメージ+15%", "ko": "HP·공격력·방어력 +2%.\n필살기 발동 시 아군 전체에서 해제할 수 있는 디버프 효과 +1.\n배리어가 부여된 아군 전체에게 약점 속성에 대해 주는 피해 +15%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n敵の攻撃で1以上ダメージを受けたときMP+5。\n味方全体の防御力+20%", "ko": "HP·공격력·방어력 +2%.\n적의 공격으로 1 이상의 피해를 받으면 MP +5.\n아군 전체의 방어력 +20%."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "pending": []}',1);
